package de.renditerechner.mobile;
import android.app.*;import android.os.*;import android.graphics.*;import android.content.*;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 final int NAVY=0xff162e45,BLUE=0xff116d83; LinearLayout root,body; EditText start,monthly,years,rate,target,age,goalAge,tax,free,inflation; Spinner mode; Switch advance,taxOn,inflOn,begin; TextView output,details; SharedPreferences prefs; int page=0;
 final String[] MODES={"Endkapital","Startkapital","Monatliche Sparrate","Spardauer","Jahresrendite","Zielvermögen"};
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("rendite_neu",0);show();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 TextView label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextColor(NAVY);v.setTextSize(size);v.setPadding(dp(2),dp(7),dp(2),dp(6));return v;}
 void show(){root=column();root.setBackgroundColor(0xfff4f7fa);setContentView(root);TextView title=label("Renditerechner",24);title.setPadding(dp(18),dp(20),0,dp(14));root.addView(title);LinearLayout nav=new LinearLayout(this);String[] tabs={"Rechner","Auswertung","Szenarien"};for(int i=0;i<3;i++){final int index=i;Button bt=new Button(this);bt.setText(tabs[i]);bt.setAllCaps(false);bt.setTextSize(12);nav.addView(bt,new LinearLayout.LayoutParams(0,dp(56),1));bt.setOnClickListener(v->{if(page==0)remember();page=index;show();});}root.addView(nav);ScrollView scroll=new ScrollView(this);root.addView(scroll);body=column();body.setPadding(dp(16),dp(12),dp(16),dp(24));scroll.addView(body);if(page==0)calculator();else if(page==1)analysis();else scenarios();}
 EditText field(String name,String key,String def){body.addView(label(name,14));EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(18);e.setInputType(8194|4096);e.setText(prefs.getString(key,def));body.addView(e);e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh();}public void afterTextChanged(Editable ed){}});return e;}
 Switch toggle(String name,String key,boolean def){Switch s=new Switch(this);s.setText(name);s.setTextColor(NAVY);s.setPadding(0,dp(12),0,dp(12));s.setChecked(prefs.getBoolean(key,def));body.addView(s);s.setOnCheckedChangeListener((b,v)->refresh());return s;}
 double num(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(" ","").replace(",","."));}
 String money(double a){return String.format(Locale.GERMANY,"%,.2f €",a);}
 void calculator(){body.addView(label("Was möchtest du berechnen?",17));mode=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,MODES);mode.setAdapter(adapter);body.addView(mode);mode.setSelection(prefs.getInt("mode",0));mode.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){refresh();}});
 start=field("Startkapital (€)","start","100000");monthly=field("Monatliche Sparrate (€)","monthly","2000");years=field("Laufzeit (Jahre)","years","15");rate=field("Erwartete Rendite (% pro Jahr)","rate","6");target=field("Zielkapital (€)","target","1500000");age=field("Aktuelles Alter","age","43");goalAge=field("Zielalter","goalAge","55");advance=toggle("Expertenmodus","expert",false);begin=toggle("Sparrate jeweils zum Monatsanfang","begin",false);taxOn=toggle("Steuerberechnung einschalten","taxOn",false);inflOn=toggle("Inflation berücksichtigen","inflOn",false);tax=field("Steuersatz (%) – vereinfacht","tax","26.375");free=field("Steuerfreibetrag (€)","free","1000");inflation=field("Inflation (% p.a.)","inflation","2");output=label("",23);details=label("",14);body.addView(output);body.addView(details);Button save=new Button(this);save.setText("Szenario speichern");body.addView(save);save.setOnClickListener(v->{remember();EditText input=new EditText(this);input.setHint("Bezeichnung");new AlertDialog.Builder(this).setTitle("Szenario speichern").setView(input).setPositiveButton("Speichern",(d,w)->save(input.getText().toString())).setNegativeButton("Abbrechen",null).show();});refresh();}
 void remember(){if(start==null)return;SharedPreferences.Editor p=prefs.edit();EditText[] es={start,monthly,years,rate,target,age,goalAge,tax,free,inflation};String[] keys={"start","monthly","years","rate","target","age","goalAge","tax","free","inflation"};for(int i=0;i<es.length;i++)p.putString(keys[i],es[i].getText().toString());p.putInt("mode",mode.getSelectedItemPosition());p.putBoolean("expert",advance.isChecked());p.putBoolean("begin",begin.isChecked());p.putBoolean("taxOn",taxOn.isChecked());p.putBoolean("inflOn",inflOn.isChecked());p.apply();}
 static double fv(double p,double a,int n,double annual,boolean begin){double r=Math.expm1(Math.log1p(annual/100)/12);double g=Math.pow(1+r,n);double factor=Math.abs(r)<1e-12?n:(g-1)/r;return p*g+a*factor*(begin?1+r:1);}
 static double solveRate(double p,double a,int n,double target,boolean begin){double lo=-99.9,hi=1000;for(int i=0;i<90;i++){double mid=(lo+hi)/2;if(fv(p,a,n,mid,begin)<target)lo=mid;else hi=mid;}return (lo+hi)/2;}
 static class Result{double p,a,rate,end,paid,tax,real;int n;}
 Result calc(){double p=num(start),a=num(monthly),y=num(years),r=num(rate),goal=num(target);if(p<0||a<0||y<0||r<=-100||r>1000||goal<0)throw new ExceptionInInitializerError("Werte außerhalb des zulässigen Bereichs");int n=(int)Math.round(y*12),m=mode.getSelectedItemPosition();boolean beg=begin.isChecked();if(m==5){n=((int)num(goalAge)-(int)num(age))*12;if(n<=0)throw new IllegalArgumentException("Zielalter muss größer als aktuelles Alter sein");m=2;}if(n<0||n>1200)throw new IllegalArgumentException("Laufzeit maximal 100 Jahre");double base=fv(p,0,n,r,beg),unit=fv(0,1,n,r,beg);
 if(m==1){double g=Math.pow(1+r/100,n/12.0);p=(goal-a*unit)/g;}
 if(m==2){if(unit==0)throw new IllegalArgumentException("Laufzeit muss größer als null sein");a=(goal-base)/unit;}
 if(m==3){if(p+a==0)throw new IllegalArgumentException("Kein Kapital und keine Sparrate");int k=0;while(k<1200&&fv(p,a,k,r,beg)<goal)k++;if(k==1200&&fv(p,a,k,r,beg)<goal)throw new IllegalArgumentException("Ziel in 100 Jahren nicht erreichbar");n=k;}
 if(m==4){if(n==0)throw new IllegalArgumentException("Laufzeit muss größer als null sein");r=solveRate(p,a,n,goal,beg);}
 if(p<0||a<0||!Double.isFinite(p+a+r))throw new IllegalArgumentException("Ziel unter diesen Annahmen nicht erreichbar");Result z=new Result();z.p=p;z.a=a;z.n=n;z.rate=r;z.end=fv(p,a,n,r,beg);z.paid=p+a*n;double profit=Math.max(0,z.end-z.paid);z.tax=taxOn.isChecked()?Math.max(0,profit-Math.max(0,num(free)))*num(tax)/100:0;z.real=(z.end-z.tax)/(inflOn.isChecked()?Math.pow(1+num(inflation)/100,n/12.0):1);return z;}
 void refresh(){if(output==null||page!=0)return;try{Result z=calc();output.setText("Endkapital: "+money(z.end));details.setText("Start: "+money(z.p)+"\nMonatlich: "+money(z.a)+"\nLaufzeit: "+String.format(Locale.GERMANY,"%.2f",z.n/12.)+" Jahre\nRendite: "+String.format(Locale.GERMANY,"%.3f",z.rate)+" %\nEinzahlungen: "+money(z.paid)+"\nErtrag: "+money(z.end-z.paid)+(taxOn.isChecked()?"\nGeschätzte Steuer: "+money(z.tax):"")+(inflOn.isChecked()?"\nHeutige Kaufkraft: "+money(z.real):""));}catch(Exception|ExceptionInInitializerError e){output.setText("Bitte Eingaben überprüfen");details.setText(e.getMessage()==null?"Ungültige Eingabe":e.getMessage());}}
 void save(String name){try{JSONArray saved=new JSONArray(prefs.getString("saved","[]"));JSONObject j=new JSONObject();j.put("name",name.trim().isEmpty()?"Szenario "+(saved.length()+1):name.trim());String[] keys={"start","monthly","years","rate","target","age","goalAge","tax","free","inflation"};for(String key:keys)j.put(key,prefs.getString(key,""));j.put("mode",prefs.getInt("mode",0));saved.put(j);prefs.edit().putString("saved",saved.toString()).apply();Toast.makeText(this,"Gespeichert",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Speichern fehlgeschlagen",Toast.LENGTH_SHORT).show();}}
 void scenarios(){body.addView(label("Gespeicherte Szenarien",21));try{JSONArray arr=new JSONArray(prefs.getString("saved","[]"));if(arr.length()==0)body.addView(label("Noch keine Szenarien vorhanden.",14));for(int i=arr.length()-1;i>=0;i--){JSONObject j=arr.getJSONObject(i);Button b=new Button(this);b.setText(j.optString("name"));body.addView(b);b.setOnClickListener(v->{SharedPreferences.Editor ed=prefs.edit();String[] keys={"start","monthly","years","rate","target","age","goalAge","tax","free","inflation"};for(String key:keys)ed.putString(key,j.optString(key,prefs.getString(key,"")));ed.putInt("mode",j.optInt("mode",0));ed.apply();page=0;show();});}}catch(Exception e){body.addView(label("Szenarien konnten nicht geladen werden.",14));}}
 void analysis(){body.addView(label("Vermögensentwicklung",21));body.addView(label("Aktuelle Berechnung mit Jahresübersicht und drei Renditeszenarien",14));double p=read("start",100000),a=read("monthly",2000),r=read("rate",6),y=read("years",15);int n=(int)Math.round(y*12);boolean beg=prefs.getBoolean("begin",false);if(n<0||n>1200||r<=-100){body.addView(label("Bitte Laufzeit und Rendite prüfen.",14));return;}body.addView(new Graph(p,a,n,r,beg));for(double change:new double[]{-2,0,2}){double v=r+change;if(v<=-100)continue;body.addView(label(String.format(Locale.GERMANY,"%.1f %%: %s",v,money(fv(p,a,n,v,beg))),16));}for(int i=0;i<=n;i+=12){double end=fv(p,a,i,r,beg);body.addView(label("Jahr "+(i/12)+"  |  "+money(end)+"  |  Ertrag: "+money(end-p-a*i),13));}if(n%12!=0)body.addView(label("Ende: "+money(fv(p,a,n,r,beg)),14));}
 double read(String key,double fallback){try{return Double.parseDouble(prefs.getString(key,""+fallback).replace(",","."));}catch(Exception e){return fallback;}}
 class Graph extends View{double p,a,r;int n;boolean b;Paint paint=new Paint(3);Graph(double p,double a,int n,double r,boolean b){super(MainActivity.this);this.p=p;this.a=a;this.n=n;this.r=r;this.b=b;}protected void onMeasure(int w,int h){setMeasuredDimension(MeasureSpec.getSize(w),dp(200));}protected void onDraw(Canvas c){super.onDraw(c);float width=getWidth()-dp(24),height=getHeight()-dp(35),left=dp(12),top=dp(15);double max=Math.max(1,fv(p,a,n,r,b));Path path=new Path();for(int i=0;i<=Math.max(1,n);i++){double val=fv(p,a,Math.min(i,n),r,b);float x=left+width*i/Math.max(1,n),y=top+height*(1-(float)(val/max));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(3));paint.setColor(BLUE);c.drawPath(path,paint);paint.setColor(0xffdde6ed);paint.setStrokeWidth(dp(1));c.drawLine(left,top+height,left+width,top+height,paint);}}
}